int search(int* nums, int numsSize, int target) {
    int lo = 0, hi = numsSize - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (nums[mid] == target) return mid;
        else if (nums[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

/* 两次二分：第一次找第一个 >= target（lower_bound），
   第二次找第一个 > target 的前一个（upper_bound-1）。
   两者都靠「nums[mid] < target 时 lo=mid+1」的模板实现。 */

